1	\N	b13630a6-6f19-11f1-b588-00155d998618	<?xml version="1.0" encoding="UTF-8"?>\n<definitions xmlns="https://www.omg.org/spec/DMN/20191111/MODEL/" xmlns:dmndi="https://www.omg.org/spec/DMN/20191111/DMNDI/" xmlns:dc="http://www.omg.org/spec/DMN/20180521/DC/" id="definitions" name="definitions" namespace="http://camunda.org/schema/1.0/dmn">\n  <decision id="matriz_aprobacion" name="Matriz de Aprobación de Crédito">\n    <decisionTable id="decisionTable_1">\n      <input id="input_monto" label="Monto del Crédito">\n        <inputExpression id="expr_monto" typeRef="integer">\n          <text>solicitud_credito_monto_aprobado</text>\n        </inputExpression>\n      </input>\n      <output id="output_rol" label="Rol Aprobador" name="rol_aprobador" typeRef="string" />\n      <rule id="rule_1">\n        <description>Nivel 1: Asesor</description>\n        <inputEntry id="in_1_1">\n          <text>&lt;= 80000</text>\n        </inputEntry>\n        <outputEntry id="out_1_1">\n          <text>"ASESOR_CREDITO"</text>\n        </outputEntry>\n      </rule>\n      <rule id="rule_2">\n        <description>Nivel 2: Jefe de Crédito</description>\n        <inputEntry id="in_2_1">\n          <text>[80001..150000]</text>\n        </inputEntry>\n        <outputEntry id="out_2_1">\n          <text>"JEFE_CREDITO"</text>\n        </outputEntry>\n      </rule>\n      <rule id="rule_3">\n        <description>Nivel 3: Subgerente de Crédito</description>\n        <inputEntry id="in_3_1">\n          <text>[150001..200000]</text>\n        </inputEntry>\n        <outputEntry id="out_3_1">\n          <text>"SUBGERENTE_CREDITO"</text>\n        </outputEntry>\n      </rule>\n      <rule id="rule_4">\n        <description>Nivel 4: Gerente de Crédito</description>\n        <inputEntry id="in_4_1">\n          <text>&gt;= 200001</text>\n        </inputEntry>\n        <outputEntry id="out_4_1">\n          <text>"GERENTE_CREDITO"</text>\n        </outputEntry>\n      </rule>\n    </decisionTable>\n  </decision>\n  <dmndi:DMNDI>\n    <dmndi:DMNDiagram>\n      <dmndi:DMNShape dmnElementRef="matriz_aprobacion">\n        <dc:Bounds height="80" width="180" x="160" y="100" />\n      </dmndi:DMNShape>\n    </dmndi:DMNDiagram>\n  </dmndi:DMNDI>\n</definitions>\n	REGLA_AW13TO	2026-06-23 10:39:16.825965	\N	Nueva Regla DMN	DEPLOYED	3
